/**
 * How a result is rendered.
 *
 * The ordering here is the pedagogy, and it is deliberate and inverted from
 * every statistics package the specification surveys:
 *
 *   1. the stability warning, if the conclusion is fragile
 *   2. the plain-language sentence, generated by the engine from the numbers
 *   3. the effect size WITH its interval
 *   4. the p-value, last and smallest
 *   5. why this test was chosen
 *   6. the ledger, if more than a couple of tests have been run
 *   7. the transcript, one click away and always present
 *
 * A p-value shown first, large, and alone is how a student learns that it is
 * the answer. It is not the answer.
 */

import { useState } from 'react'
import type { LogEntry } from '../lib/store'
import { fmt, fmtP, type Transcript } from '../lib/engine'

export function ResultCard({ entry, children }: { entry: LogEntry; children?: React.ReactNode }) {
  const r = entry.result
  const stability = r.stability as any
  const ledger = r.ledger as any
  const assumptions = (r.assumption_checks as any[]) ?? []

  if (r.error) {
    return (
      <article className="card err">
        <h3>That did not run</h3>
        <p>{String(r.message ?? r.error)}</p>
      </article>
    )
  }

  if (r.refused) {
    return (
      <article className="card refused">
        <header>
          <span className="pill warn">refused</span>
          <h3>{entry.label}</h3>
        </header>
        <p>{String(r.reason)}</p>
        {r.suggestion ? <p className="muted">{String(r.suggestion)}</p> : null}
        {r.descriptives ? <Descriptives data={r.descriptives as any} /> : null}
        <TranscriptToggle transcript={entry.transcript} wallMs={entry.wallMs} />
      </article>
    )
  }

  return (
    <article className="card">
      <header>
        <h3>{entry.label}</h3>
        {r.test_label ? <span className="pill">{String(r.test_label)}</span> : null}
      </header>

      {stability?.ran && stability.severity !== 'info' ? (
        <div className={`banner ${stability.severity}`}>
          <strong>{stability.severity === 'block' ? 'This result is not stable' : 'Read this first'}</strong>
          <p>{stability.verdict}</p>
        </div>
      ) : null}

      {r.plain_language ? <p className="lede">{String(r.plain_language)}</p> : null}

      {typeof r.effect_size === 'number' ? (
        <div className="stats">
          <Stat
            label="How big is the difference"
            value={fmt(r.effect_size)}
            unit={String(r.effect_size_type ?? '').replace(/_/g, ' ')}
            note={
              Array.isArray(r.ci) && Number.isFinite((r.ci as number[])[0])
                ? `95% CI ${fmt((r.ci as number[])[0])} to ${fmt((r.ci as number[])[1])}`
                : String(r.effect_interpretation ?? '')
            }
            emphasis
          />
          {r.p_value != null ? (
            <Stat
              label="Could chance explain it"
              value={fmtP(r.p_value)}
              note={
                (r.p_value as number) < 0.05
                  ? 'chance rarely produces a difference this big'
                  : 'chance produces differences this big often enough'
              }
            />
          ) : null}
          {stability?.ran ? (
            <Stat
              label="Does it survive perturbation"
              value={`${Math.round((stability.agreement ?? 0) * 100)}%`}
              note={`of ${stability.n_perturbations} re-runs agreed`}
            />
          ) : null}
        </div>
      ) : null}

      {r.why_this_test ? (
        <details className="why">
          <summary>Why this test?</summary>
          <p>{String(r.why_this_test)}</p>
          {assumptions.length ? (
            <ul className="checks">
              {assumptions.map((a) => (
                <li key={a.name} className={a.severity}>
                  <strong>{a.name.replace(/_/g, ' ')}</strong>: {a.detail}
                </li>
              ))}
            </ul>
          ) : null}
        </details>
      ) : null}

      {Array.isArray(r.posthoc) && (r.posthoc as any[]).length ? (
        <PostHoc rows={r.posthoc as any[]} />
      ) : null}

      {children}

      {ledger && ledger.tests_run_so_far >= 2 ? (
        <div className={`banner ${ledger.severity}`}>
          <strong>Multiple-comparison ledger</strong>
          <p>{ledger.message}</p>
        </div>
      ) : null}

      {Array.isArray(r.notes) && (r.notes as string[]).length ? (
        <ul className="notes">
          {(r.notes as string[]).map((n, i) => (
            <li key={i}>{n}</li>
          ))}
        </ul>
      ) : null}

      {r.teaches ? <p className="teaches">{String(r.teaches)}</p> : null}

      <TranscriptToggle transcript={entry.transcript} wallMs={entry.wallMs} />
    </article>
  )
}

function Stat({ label, value, unit, note, emphasis }: {
  label: string; value: string; unit?: string; note?: string; emphasis?: boolean
}) {
  return (
    <div className={`stat${emphasis ? ' primary' : ''}`}>
      <div className="v">{value}</div>
      {unit ? <div className="u">{unit}</div> : null}
      <div className="l">{label}</div>
      {note ? <div className="n">{note}</div> : null}
    </div>
  )
}

function Descriptives({ data }: { data: Record<string, any> }) {
  return (
    <div className="tscroll">
      <table>
        <thead>
          <tr><th>group</th><th>n</th><th>mean</th><th>sd</th><th>min</th><th>max</th></tr>
        </thead>
        <tbody>
          {Object.entries(data).map(([g, d]) => (
            <tr key={g}>
              <td>{g}</td><td>{d.n}</td><td>{fmt(d.mean)}</td>
              <td>{fmt(d.sd)}</td><td>{fmt(d.min)}</td><td>{fmt(d.max)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function PostHoc({ rows }: { rows: any[] }) {
  return (
    <details className="why" open>
      <summary>Which pairs differ? ({rows.length} comparisons, Holm-corrected)</summary>
      <div className="tscroll">
        <table>
          <thead>
            <tr><th>pair</th><th>effect</th><th>p (raw)</th><th>p (corrected)</th><th></th></tr>
          </thead>
          <tbody>
            {rows.map((p, i) => (
              <tr key={i}>
                <td>{p.a} vs {p.b}</td>
                <td>{fmt(p.effect_size, 2)}</td>
                <td>{fmt(p.p_raw, 4)}</td>
                <td>{fmt(p.p_adjusted, 4)}</td>
                <td>{p.significant ? <span className="pill ok">holds</span> : <span className="pill">not after correction</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </details>
  )
}

export function TranscriptToggle({ transcript, wallMs }: {
  transcript: Transcript | null; wallMs?: number
}) {
  const [open, setOpen] = useState(false)
  if (!transcript) {
    // This should be unreachable: the invariant is that a rendered number has a
    // transcript. If it ever happens, say so loudly rather than rendering
    // something that looks authoritative.
    return (
      <p className="banner block">
        <strong>No execution record.</strong> This output is not bound to a computation and
        should not be trusted or quoted.
      </p>
    )
  }
  return (
    <div className="transcript">
      <button className="linkish" onClick={() => setOpen((v) => !v)}>
        {open ? '▾' : '▸'} execution record · <code>{transcript.transcript_id}</code>
      </button>
      {open ? (
        <div className="tbody">
          <dl>
            <dt>tool</dt><dd><code>{transcript.tool}</code></dd>
            <dt>call</dt><dd><code>{transcript.call}</code></dd>
            <dt>engine</dt>
            <dd>
              <code>
                {Object.entries(transcript.engine)
                  .filter(([k]) => ['scipy', 'numpy', 'python', 'runtime', 'phagequest-engine'].includes(k))
                  .map(([k, v]) => `${k} ${v}`)
                  .join(' · ')}
              </code>
            </dd>
            <dt>data fingerprint</dt><dd><code>{transcript.data_id ?? '—'}</code></dd>
            <dt>ran in</dt>
            <dd>{transcript.duration_ms.toFixed(1)} ms{wallMs ? ` (${wallMs} ms including the round trip)` : ''}</dd>
            <dt>parameters</dt>
            <dd><pre>{JSON.stringify(transcript.params, null, 2)}</pre></dd>
            <dt>raw output</dt>
            <dd><pre>{JSON.stringify(trimForDisplay(transcript.result), null, 2)}</pre></dd>
          </dl>
          <p className="muted small">
            This record is what licenses every number above. Nothing on this screen was written
            by a language model.
          </p>
        </div>
      ) : null}
    </div>
  )
}

/** Keep the raw-output view readable: long arrays are summarised, not dumped. */
function trimForDisplay(obj: unknown): unknown {
  if (Array.isArray(obj)) {
    if (obj.length > 12) return [`…${obj.length} values…`, ...obj.slice(0, 4).map(trimForDisplay)]
    return obj.map(trimForDisplay)
  }
  if (obj && typeof obj === 'object') {
    return Object.fromEntries(
      Object.entries(obj as Record<string, unknown>).map(([k, v]) => [k, trimForDisplay(v)]),
    )
  }
  return obj
}
